package vn.svframe.svframelib.module;import java.util.function.Supplier;public final class ListenerToggle{private final Supplier<?> supplier;private Object instance;public ListenerToggle(Module module,Supplier<?> supplier){this.supplier=supplier;}public ListenerToggle(MMOPlugin plugin,Supplier<?> supplier){this.supplier=supplier;}public synchronized void toggle(boolean flag){if(flag&&instance==null)instance=supplier.get();else if(!flag)instance=null;}public void disable(){toggle(false);}public boolean enabled(){return instance!=null;}}